"""Semantic desk tests, not a Celan grammar validator or native-speaker trial."""
import csv,json,hashlib
from pathlib import Path
from fractions import Fraction
root=Path(__file__).resolve().parents[2];out=Path(__file__).parent
files=['dictionary_senses.csv','dictionary_examples.csv','grammar_guide.csv','dictionary_entries.csv']
hashes={f:hashlib.sha256((root/'dictionary/app_data'/f).read_bytes()).hexdigest() for f in files}
senses=list(csv.DictReader((root/'dictionary/app_data/dictionary_senses.csv').open()))
examples=list(csv.DictReader((root/'dictionary/app_data/dictionary_examples.csv').open()))
keys={'thal','ther','reth','shen','shenlian','worlian','belshen','shena','morlak','karethaen','tal','shan','vorkor','deni','denya','del','tren','peth'}
evidence=[{k:r[k] for k in ['headword_id','word_type','meaning','usage_note','sense_id']} for r in senses if r['headword_id'] in keys and r['visible']=='Yes']
(out/'evidence.json').write_text(json.dumps({'source_hashes':hashes,'visible_senses':evidence,'established_examples':[r for r in examples if r['headword_id'] in ['worlian','shenlian','ther','belshen']]},ensure_ascii=False,indent=2)+'\n')
cases=[]
def add(id,topic,celan,intent,context,result,reason):cases.append(dict(id=id,topic=topic,celan=celan,intent=intent,context=context,result=result,reason=reason))
add('F1','Fractions','va karethaen unar thal del dren.','Use half the water.','One identified supply of water.','Proposed reusable construction','Thal supplies out of; treating the two as equal shares of the whole is the explicit new convention needed.')
add('F2','Fractions','va karethaen unar thal quen dren.','Use a quarter of the water.','Same whole, four equal shares.','Proposed reusable construction','Same structure scales without adding a word for quarter.')
add('F3','Fractions','va karethaen tren thal quen dren.','Use three quarters of the water.','Same whole, four equal shares.','Proposed reusable construction','The numerator selects three shares; the denominator fixes four equal shares.')
add('F4','Fractions','va karethaen unar thal del dren.','Use half the combined water.','Two containers hold unequal quantities.','Fails if interpreted as choose one container','One of two containers need not contain half the total. The fraction must describe equal abstract shares, not count existing containers.')
add('F5','Fractions','va karethaen unar thal verin dren.','Use one zeroth of the water.','Denominator zero.','Reject under proposed fraction rule','No division into zero equal shares is defined.')
add('F6','Fractions','va karethaen peth thal quen dren.','Use five quarters of the water.','Only one bounded supply is available.','Needs a reference-unit explanation','Five quarters is mathematically meaningful but cannot be taken from one whole supply. Distinguish a reference unit from the entire available stock.')
add('O1','Positions','va var shan vorkor «tren».','Go through door labelled three.','Doors have visible number labels.','Strong contextual composition','The quoted number identifies the label; no ordinal suffix or new meaning is needed.')
add('O2','Positions','va var shan vorkor «tren».','Go through the third door encountered.','Unlabelled doors; walking direction not stated.','Does not establish a general ordinal','The label construction alone supplies neither counting direction nor a starting point.')
add('O3','Positions','va var shan vorkor «tren».','Go through the third door counted from the agreed start.','Speaker and listener first number the doors together.','Works with shared numbering','The earlier counting supplies the order. This is a contextual solution, not a universal ordinal rule.')
add('O4','Positions','va tal emilpral «del» var I.','Give me plate labelled two.','Plates are numbered for a task.','Strong contextual composition','Repeats the label strategy with another noun; does not mean give me two plates.')
add('B1','Minimum amount','rinaen peth shen morlak worlian.','Five measures of grain are enough.','Preparing a meal with a shared measure.','Supported compositional paraphrase','Worlian already appears as a predicate. This states sufficiency, not an exact minimum.')
add('B2','Minimum amount','rinaen peth shen morlak worlian. ver rinaen quen shen morlak worlian.','Five measures suffice; four do not.','Only whole measures are offered; larger supplies are useful.','Useful contextual workaround','Gives a practical threshold in this scenario. It does not resolve every quantity between four and five or independently promise that excess is acceptable.')
add('B3','Minimum amount','peth reth ther peth','Five or more.','An amount expression.','Promising but new numeric construction','Reth and Ther have the right semantic ingredients, but current Ther syntax compares a stated quality: X adjective Ther Y. A bare-number comparison must be explicitly established.')
add('B4','Minimum amount','rinaen peth shen morlak worlian. ver rinaen quen shen morlak worlian.','The minimum is exactly five.','4.5 measures are possible.','Insufficient for an exact lower bound','The clauses leave 4.5 unsettled. Do not label this wording an exact at-least construction.')
add('E1','Equal amount','va tal peth shen morlak var I.','Give me the same amount as the other recipient.','The other recipient received five of the same measure of grain.','Works by repeating the known quantity','Numerical equality is communicated without a separate same word, provided the measure is shared.')
add('E2','Equal amount','va tal unar shen morlak var Ya. va tal unar shen morlak var I.','Give us equal amounts.','One calibrated measure is used for both recipients.','Works through matched instructions','Two equal unit amounts establish equality operationally, without Thaleth.')
add('E3','Equal amount','va tal shen denya var I.','Give me the same amount as that.','The listener indicates a reference measure.','Understandable but potentially ambiguous','May request the measure itself or a measured quantity matching it. Use a named material and explicit count when precision matters.')
add('E4','Equal amount','va tal shenlian var I.','Give me the same amount.','No shared reference amount.','Does not preserve the instruction reliably','Shenlian names a standard/reference measure, not equality to an unnamed earlier quantity.')
add('P1','Price','rinaen peth shen morlak-ka belshen peth shena.','The total price of five measures of grain is five coins.','One agreed measure and one understood currency.','Strong candidate composition','Read the possessor as the full phrase five measures of grain. No new price word is required; the phrase boundary should be taught explicitly.')
add('P2','Price','rinaen unar shen morlak-ka belshen del shena.','One measure of grain costs two coins.','Same market convention.','Strong candidate composition','Changes quantity and price independently, so the example does not depend on both numbers being five.')
add('P3','Price','rinaen peth shen morlak-ka belshen peth shena.','Each of five measures costs five coins.','Seller intends a total of twenty-five coins.','Wrong for this intention','The proposed wording states the price for the five-measure lot, not five coins per individual measure.')
add('P4','Price','rinaen peth shen morlak-ka belshen peth shena.','A fully specified price independent of market context.','Different measuring vessels or currencies are possible.','Needs the unit and currency clarified','Coin type and measure must be shared or specified. This is a missing reference, not necessarily missing grammar. Counted Shena versus Shenan remains a separate teaching decision.')
(out/'cases.json').write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
# Arithmetic checks validate the proposed interpretation, NOT Celan acceptability.
assert Fraction(1,2)==Fraction(2,4)
assert Fraction(1,4)+Fraction(3,4)==1
assert Fraction(1,4)!=Fraction(1,2) # one container holding 1 of a 1+3 total
for amount in [Fraction(4),Fraction(9,2),Fraction(5),Fraction(6)]:
 assert ((amount==5) or (amount>5))==(amount>=5)
assert 5*5==25
for f,h in hashes.items():assert hashlib.sha256((root/'dictionary/app_data'/f).read_bytes()).hexdigest()==h
summary={'method':'Manual compositional and ambiguity review against current app meanings and grammar. Arithmetic checks verify intended boundaries only. No native-speaker or independent comprehension test was performed.','cases':len(cases),'new_headwords_added':0,'grammar_rules_added':0,'source_files_unchanged':True,'arithmetic_checks':'passed','new_words_needed_now':'No new root or -eth form justified by these tests; fraction and numeric-comparison conventions remain proposals.'}
(out/'results.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=['# Celan composition tests: sharing, counting and ordering','',summary['method'],'','These are experimental compositions, not new approved dictionary examples. Existing app and grammar files were not changed. No -eth forms were introduced.','', '## Findings','', '- Fractions: the proposed numerator + thal + denominator pattern is reusable if equal shares and a shared whole are explicit in the rule. It is not already established by the ordinary meaning of thal.', '- Positions: numbered labels work contextually. Labels alone do not establish an ordinal sequence or its starting point.', '- Minimum amounts: enough/not enough works in practical scenes. Exact five-or-more needs a numerical use of ther, extending its currently taught adjective comparison.', '- Equality: repeat a known count or apply the same unit to both recipients. A general unknown-amount equality statement remains unresolved; shenlian alone does not solve it.', '- Prices: quantity phrase + -ka + belshen is a strong compositional candidate. Distinguish whole-lot price from price per measure.','', '## All 22 tests','']
for c in cases:
 lines += ['### '+c['id']+' — '+c['topic'],'','**Celan:** '+c['celan'],'','**Intention:** '+c['intent'],'','**Situation:** '+c['context'],'','**Result:** '+c['result'],'',c['reason'],'']
lines+=['## Recommended next decisions','','1. Test the fraction construction with the explicit equal-share interpretation; start with zero through one whole and explain improper fractions separately.','2. Keep numbered-label expressions available without claiming they establish a full ordinal system.','3. Develop and test bare-number ther comparisons and coordinated equal-or-greater amounts.','4. Use matching counts for equality now; investigate a general equality construction only where the counts are unknown.','5. Review the price examples and whole-phrase possession as sentence constructions.','', 'These tests do not authorize adding words, changing definitions, or publishing new learner rules.']
(out/'report.md').write_text('\n'.join(lines)+'\n')
print(json.dumps(summary,indent=2))
